cd <WORKSPACE>/smb-infrastructure-dashboard
agent-browser open "http://localhost:3460/login" 2>&1 | tail -1
sleep 2
# Set both inputs via native setter + React events in one eval, then submit the form
agent-browser eval "(()=>{
  const set=(el,v)=>{const d=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;d.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));};
  const u=document.querySelector('input[name=username]')||document.querySelectorAll('input')[0];
  const p=document.querySelector('input[type=password]');
  set(u,'operator');set(p,'operator123');
  return 'u='+u.value+' p='+p.value;
})()" 2>&1 | tail -1
sleep 1
agent-browser eval "(()=>{const b=[...document.querySelectorAll('button')].find(x=>/^Sign in$/i.test(x.textContent.trim()));b.click();return 'submitted'})()" 2>&1 | tail -1
sleep 4
echo "path: $(agent-browser eval "location.pathname" 2>&1 | tail -1)"
